import math
import random

def pack_circles():
    best_config = None
    best_sum = 0

    for seed in range(400):
        random.seed(seed)
        config = greedy_pack()

        if len(config) == 13 and is_valid(config):
            total = sum(r for _, _, r in config)
            if total > best_sum:
                best_sum = total
                best_config = config

    return best_config

def greedy_pack():
    circles = []

    for _ in range(13):
        best_r = 0
        best_xy = None

        for _ in range(200):
            x = random.random()
            y = random.random()

            r = min(x, y, 1-x, 1-y)

            for cx, cy, cr in circles:
                d = math.sqrt((x-cx)**2 + (y-cy)**2)
                r = min(r, d - cr)

            if r > best_r:
                best_r = r
                best_xy = (x, y)

        if best_xy and best_r > 1e-9:
            circles.append([best_xy[0], best_xy[1], best_r])

    return circles

def is_valid(config):
    if len(config) != 13:
        return False

    for x, y, r in config:
        if x - r < -1e-9 or x + r > 1 + 1e-9 or y - r < -1e-9 or y + r > 1 + 1e-9:
            return False

    for i in range(13):
        for j in range(i+1, 13):
            x1, y1, r1 = config[i]
            x2, y2, r2 = config[j]
            d = math.sqrt((x1-x2)**2 + (y1-y2)**2)
            if d < r1 + r2 - 1e-9:
                return False

    return True

