import math

def max_radius(x, y, circles):
    r = min(x, 1 - x, y, 1 - y)
    for cx, cy, cr in circles:
        d = math.sqrt((x - cx)**2 + (y - cy)**2)
        if d > 1e-10:
            r = min(r, d - cr)
    return max(0, r)

candidates = []
for i in range(5):
    for j in range(5):
        candidates.append(((i + 0.5) / 5, (j + 0.5) / 5))

circles = []

for _ in range(13):
    best_idx = -1
    best_r = -1

    for i in range(len(candidates)):
        x, y = candidates[i]
        r = max_radius(x, y, circles)
        if r > best_r and r > 1e-10:
            best_r = r
            best_idx = i

    if best_idx == -1:
        break

    x, y = candidates[best_idx]
    circles.append([x, y, best_r])
    candidates.pop(best_idx)

for _ in range(10):
    changed = False
    for i in range(len(circles)):
        x, y = circles[i][0], circles[i][1]
        other_circles = [circles[j] for j in range(len(circles)) if j != i]
        new_r = max_radius(x, y, other_circles)
        if new_r > circles[i][2] + 1e-9:
            circles[i][2] = new_r
            changed = True
    if not changed:
        break

print(circles)
